// Keeps a phone's screen on while it is in a game.
// Screen Wake Lock needs HTTPS, so on a plain http:// LAN address it falls back to a tiny silent looping
// video, which browsers treat as "something is playing" and do not put to sleep.
const MP4 = "data:video/mp4;base64,";
const WEBM = "data:video/webm;base64,";

let lock = null;
let video = null;
let wanted = false;

async function request() {
  if (!wanted) return;
  if ("wakeLock" in navigator) {
    try {
      lock = await navigator.wakeLock.request("screen");
      lock.addEventListener("release", () => { lock = null; });
      return;
    } catch { /* not allowed here, try the video */ }
  }
  if (!video) {
    video = document.createElement("video");
    video.muted = true;
    video.loop = true;
    video.setAttribute("playsinline", "");
    video.setAttribute("aria-hidden", "true");
    video.style.cssText = "position:fixed;width:1px;height:1px;opacity:.01;pointer-events:none;left:0;top:0";
    video.src = video.canPlayType("video/mp4") ? MP4 : WEBM;
    document.body.appendChild(video);
  }
  video.play().catch(() => {});
}

export function keepAwake() {
  if (wanted) return;
  wanted = true;
  request();
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible" && wanted && !lock) request();
  });
}
